}

problems.solutionCode:
export type LoanReceipt = { readonly receiptId: string; borrowerNote: string };

export function updateBorrowerNote(receipt: LoanReceipt, nextNote: string): LoanReceipt {
  return { receiptId: receipt.receiptId, borrowerNote: nextNote };
}

const receiptIdentityWitness: Pick<LoanReceipt, 'receiptId'> = { receiptId: 'LOAN-204' };
// @ts-expect-error receiptId is readonly in the exported type.
receiptIdentityWitness.receiptId = 'LOAN-205';

