export type BillingState = string;

export function describeBillingState(_state: BillingState): string {
  return '';
}

problems.solutionCode:
export type BillingState = 'pending' | 'active' | 'paused';

const billingLabels: Record<BillingState, string> = {
  pending: 'Payment pending',
  active: 'Subscription active',
  paused: 'Subscription paused',
};

type Equal<Left, Right> = (<Value>() => Value extends Left ? 1 : 2) extends (<Value>() => Value extends Right ? 1 : 2) ? true : false;
type Assert<Condition extends true> = Condition;
export type BillingStateExactnessWitness = Assert<Equal<BillingState, 'pending' | 'active' | 'paused'>>;

export function describeBillingState(state: BillingState): string {
  return Object.hasOwn(billingLabels, state)
    ? billingLabels[state]
    : 'Unknown billing state';
}

problems.trapMutant:
export type BillingState = string;

export function describeBillingState(state: BillingState): string {
  if (state === 'pending') return 'Payment pending';
  if (state === 'active') return 'Subscription active';
  if (state === 'paused') return 'Subscription paused';
  return state;
}

