problems.starterCode:
export type EvaluationOptions = { flagKey?: string; region?: string; tenant?: string };

export function buildEvaluationOptions(flagKey: string, region?: string): EvaluationOptions {
  return { flagKey, region, tenant: undefined };
}

problems.solutionCode:
export type EvaluationOptions = { flagKey: string; region?: string };

export function buildEvaluationOptions(flagKey: string, region?: string): EvaluationOptions {
  const options: EvaluationOptions = { flagKey };
  if (region !== undefined) {
    options.region = region;
  }
  return options;
}

